(7327430, 1144052, 179667, '<td valign="top">Gorgeous!  Awesome tones and the flare is just an added bonus!</td>', 'Gorgeous!  Awesome tones and the flare is just an added bonus!', '2015-03-16 00:13:45.000000', NULL, 1),
(7327494, 1144372, 109227, '<td valign="top"><strike></strike></td>', '', '2015-03-16 08:14:38.000000', NULL, 1),
(7327522, 1144373, 33068, '<td valign="top">Great composition and processing.  The lens flare really sets the mood for the shot.  Top 3.</td>', 'Great composition and processing.  The lens flare really sets the mood for the shot.  Top 3.', '2015-03-16 10:20:05.000000', NULL, 1),
(7327524, 1144299, 33068, '<td valign="top">Beautiful model, nice pose, and the lens flare really sets the mood.  I also like the purple tones with her skin and hair.  Top 3.</td>', 'Beautiful model, nice pose, and the lens flare really sets the mood.  I also like the purple tones with her skin and hair.  Top 3.', '2015-03-16 10:25:09.000000', NULL, 1),
(7327526, 1143934, 33068, '<td valign="top">I''ll start off with I''m a sucker for any photo with a tree in it.  You really framed the tree nicely and the lens flare adds to the shot.  Well done.  7</td>', 'I''ll start off with I''m a sucker for any photo with a tree in it.  You really framed the tree nicely and the lens flare adds to the shot.  Well done.  7', '2015-03-16 10:27:44.000000', NULL, 1),
(7327528, 1144085, 33068, '<td valign="top">Nice color contrast.</td>', 'Nice color contrast.', '2015-03-16 10:28:18.000000', NULL, 1),
(7327530, 1144328, 33068, '<td valign="top">The post processing is nice as well as the light on the parachute.  I would have liked to seen a more significant lens flare though.  At first I thought it was just a cloud.</td>', 'The post processing is nice as well as the light on the parachute.  I would have liked to seen a more significant lens flare though.  At first I thought it was just a cloud.', '2015-03-16 10:31:07.000000', NULL, 1),
(7327531, 1144384, 33068, '<td valign="top">Unique take on the challenge.</td>', 'Unique take on the challenge.', '2015-03-16 10:32:46.000000', NULL, 1),
(7327532, 1144360, 33068, '<td valign="top">I feel as if the lens flare is working against the shot in this case.  It makes it hard to tell what is going on.</td>', 'I feel as if the lens flare is working against the shot in this case.  It makes it hard to tell what is going on.', '2015-03-16 10:34:30.000000', NULL, 1),
(7327533, 1143928, 33068, '<td valign="top">I wouldn''t have known that was a dog if it wasn''t for the title.  The focus is off and the image is a little grainy.</td>', 'I wouldn''t have known that was a dog if it wasn''t for the title.  The focus is off and the image is a little grainy.', '2015-03-16 10:38:03.000000', NULL, 1),
(7327534, 1144197, 96751, '<td valign="top">Best looking thumbnail on the page</td>', 'Best looking thumbnail on the page', '2015-03-16 10:38:32.000000', NULL, 1),
